import { useState } from "react";
import axios from "axios";
import "./App.css";

export default function Login({ onBack, onLoginSuccess, onNavigateToRegister }) {
  const [email, setEmail] = useState("");
  const [password, setPassword] = useState("");
  const [otp, setOtp] = useState("");
  const [token, setToken] = useState("");
  const [error, setError] = useState("");
  const [loading, setLoading] = useState(false);

  // Validare în timp real
  const [emailValid, setEmailValid] = useState(false);
  const [passwordValid, setPasswordValid] = useState(false);
  const [otpValid, setOtpValid] = useState(false);

  const validateEmailField = (value) => {
    const emailRegex = /^[^\s@]+@[^\s@]+\.[^\s@]+$/;
    setEmailValid(emailRegex.test(value));
  };

  const validatePasswordField = (value) => {
    setPasswordValid(value.length >= 8);
  };

  const validateOtpField = (value) => {
    const otpRegex = /^[0-9]{6}$/;
    setOtpValid(otpRegex.test(value));
  };

  const validateLogin = () => {
    if (!email || !password || !otp) {
      setError("Te rog completează toate câmpurile!");
      return false;
    }

    // Validare format email
    const emailRegex = /^[^\s@]+@[^\s@]+\.[^\s@]+$/;
    if (!emailRegex.test(email)) {
      setError("Adresa de email nu este validă!");
      return false;
    }

    // Validare lungime minimă parolă
    if (password.length < 8) {
      setError("Parola trebuie să aibă minim 8 caractere!");
      return false;
    }

    // Validare format OTP (exact 6 cifre)
    const otpRegex = /^[0-9]{6}$/;
    if (!otpRegex.test(otp)) {
      setError("Codul 2FA trebuie să fie format din 6 cifre!");
      return false;
    }

    setError("");
    return true;
  };

  const handleLogin = async () => {
    if (!validateLogin()) return;

    setLoading(true);
    setError("");

    try {
      const res = await axios.post("http://localhost:8001/login", { 
        email, 
        password, 
        otp_code: otp 
      });

      if (res.data.token) {
        setToken(res.data.token);
        setError("");
        // Redirect to main page after 2 seconds
        setTimeout(() => {
          onLoginSuccess(res.data.token, email);
        }, 2000);
      } else if (res.data.error) {
        setError(res.data.error);
      }
    } catch (err) {
      setError("Eroare la autentificare. Verifică datele introduse!");
    } finally {
      setLoading(false);
    }
  };

  return (
    <div className="animated-bg" style={{ minHeight: "100vh", paddingBottom: "2rem" }}>
      {/* Header */}
      <header className="header">
        <div className="header-content">
          <div className="logo" onClick={onBack} style={{ cursor: "pointer" }}>
            🍳 SmartChef
          </div>
        </div>
      </header>

      <div className="form-container">
        <div style={{ textAlign: "center", marginBottom: "2rem" }}>
          <h2 style={{ fontSize: "2.2rem", fontWeight: "700", color: "#ff6b35", marginBottom: "0.5rem" }}>
            Login
          </h2>
          <p style={{ color: "#666", fontSize: "1rem" }}>
            Intră în contul tău SmartChef
          </p>
        </div>

        {error && (
          <div style={{
            background: "#fee",
            border: "2px solid #fcc",
            borderRadius: "12px",
            padding: "1rem",
            marginBottom: "1.5rem",
            color: "#c33",
            fontWeight: "500"
          }}>
            ⚠️ {error}
          </div>
        )}

        {token && (
          <div style={{
            background: "linear-gradient(135deg, #e8f5e9 0%, #c8e6c9 100%)",
            border: "3px solid #4CAF50",
            borderRadius: "12px",
            padding: "1.5rem",
            marginBottom: "1.5rem"
          }}>
            <p style={{ color: "#2e7d32", fontWeight: "600", fontSize: "1.1rem", marginBottom: "0.5rem" }}>
              ✅ Autentificare reușită!
            </p>
            <p style={{ color: "#666", fontSize: "0.9rem", wordBreak: "break-all", marginBottom: "0.5rem" }}>
              <strong>Token:</strong> {token}
            </p>
            <p style={{ color: "#2e7d32", fontSize: "0.95rem", fontWeight: "600", marginTop: "0.8rem" }}>
              ⏳ Redirecționare în 2 secunde...
            </p>
          </div>
        )}

        <div className="form-group">
          <label className="form-label">Email</label>
          <div style={{ position: "relative" }}>
            <input
              className="form-input"
              type="email"
              placeholder="exemplu@email.com"
              value={email}
              onChange={e => {
                setEmail(e.target.value);
                validateEmailField(e.target.value);
              }}
              style={{ paddingRight: emailValid ? "3rem" : "1rem" }}
            />
            {emailValid && (
              <span style={{
                position: "absolute",
                right: "1rem",
                top: "50%",
                transform: "translateY(-50%)",
                color: "#4CAF50",
                fontSize: "1.5rem",
                fontWeight: "bold"
              }}>
                ✓
              </span>
            )}
          </div>
        </div>

        <div className="form-group">
          <label className="form-label">Parolă</label>
          <div style={{ position: "relative" }}>
            <input
              className="form-input"
              type="password"
              placeholder="Introdu parola"
              value={password}
              onChange={e => {
                setPassword(e.target.value);
                validatePasswordField(e.target.value);
              }}
              style={{ paddingRight: passwordValid ? "3rem" : "1rem" }}
            />
            {passwordValid && (
              <span style={{
                position: "absolute",
                right: "1rem",
                top: "50%",
                transform: "translateY(-50%)",
                color: "#4CAF50",
                fontSize: "1.5rem",
                fontWeight: "bold"
              }}>
                ✓
              </span>
            )}
          </div>
        </div>

        <div className="form-group">
          <label className="form-label">Cod 2FA</label>
          <div style={{ position: "relative" }}>
            <input
              className="form-input"
              type="text"
              placeholder="Codul din Google Authenticator"
              value={otp}
              onChange={e => {
                setOtp(e.target.value);
                validateOtpField(e.target.value);
              }}
              maxLength={6}
              style={{ paddingRight: otpValid ? "3rem" : "1rem" }}
            />
            {otpValid && (
              <span style={{
                position: "absolute",
                right: "1rem",
                top: "50%",
                transform: "translateY(-50%)",
                color: "#4CAF50",
                fontSize: "1.5rem",
                fontWeight: "bold"
              }}>
                ✓
              </span>
            )}
          </div>
            onChange={e => setOtp(e.target.value)}
            maxLength="6"
          />
          <p style={{ fontSize: "0.85rem", color: "#999", marginTop: "0.3rem" }}>
            📱 Introdu codul din aplicația ta de autentificare
          </p>
        </div>

        <button
          className="btn btn-primary"
          onClick={handleLogin}
          disabled={loading}
          style={{ 
            width: "100%", 
            padding: "1rem", 
            fontSize: "1.1rem", 
            marginTop: "1rem",
            opacity: loading ? 0.6 : 1,
            cursor: loading ? "not-allowed" : "pointer"
          }}
        >
          {loading ? "🔄 Se verifică..." : "🔐 Login"}
        </button>

        <button
          className="btn btn-secondary"
          onClick={onBack}
          style={{ width: "100%", padding: "1rem", fontSize: "1.1rem", marginTop: "1rem" }}
        >
          ← Înapoi
        </button>

        <p style={{ textAlign: "center", marginTop: "2rem", color: "#666" }}>
